sp_widget.client_script:
api.controller = function() {
    var c = this;

    c.search = '';
    c.statusFilter = 'all';
    c.modeFilter = 'all';
    c.selectedInterview = null;

    c.getFilteredInterviews = function() {

        var interviews = c.data.interviews || [];
        var results = [];
        var searchText = String(c.search || '').toLowerCase().trim();

        for (var i = 0; i < interviews.length; i++) {

            var interview = interviews[i];

            var matchesSearch = true;
            var matchesStatus = true;
            var matchesMode = true;

            if (searchText) {

                var searchable =
                    String(interview.student || '') + ' ' +
                    String(interview.studentId || '') + ' ' +
                    String(interview.opportunity || '') + ' ' +
                    String(interview.company || '') + ' ' +
                    String(interview.interviewer || '');

                matchesSearch =
                    searchable.toLowerCase().indexOf(searchText) !== -1;
            }

            if (c.statusFilter !== 'all') {
                matchesStatus =
                    String(interview.status || '') ===
                    String(c.statusFilter);
            }

            if (c.modeFilter !== 'all') {
                matchesMode =
                    String(interview.mode || '') ===
                    String(c.modeFilter);
            }

            if (matchesSearch && matchesStatus && matchesMode) {
                results.push(interview);
            }
        }

        return results;
    };

    c.openInterview = function(interview) {
        c.selectedInterview = interview;
    };

    c.closeInterview = function() {
        c.selectedInterview = null;
    };

    c.refresh = function() {
        c.server.update();
    };
};

