   CAMPUS360 TPO FULL SCREEN EDGE-TO-EDGE RESET
   ========================================================= */

body #sp-header,
body .sp-header,
body .sp-navbar,
body .navbar.sp-navbar,
body #sp-nav-bar,
body .sp-nav-bar,
body header#sp-header,
body header.sp-header,
