    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    border: none !important;
}

.c360-page {
  padding: 28px;
  background: #f6f8fb;
  min-height: 100vh;
  color: #172033;
  font-family: Arial, sans-serif;
}

.c360-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
}

.c360-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: #64748b;
  margin-bottom: 7px;
}

.c360-header h1 {
  margin: 0;
  font-size: 28px;
}

.c360-header p {
  margin: 7px 0 0;
  color: #64748b;
}

.c360-refresh {
  border: 1px solid #d8dee8;
  background: white;
  padding: 10px 15px;
  border-radius: 8px;
  cursor: pointer;
  font-weight: 600;
}

.c360-refresh span {
  margin-right: 5px;
}

.c360-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}

.c360-stat {
  background: white;
  border: 1px solid #e4e8ef;
  border-radius: 12px;
  padding: 19px;
}

.stat-label {
  font-size: 12px;
  color: #64748b;
}

.stat-value {
  font-size: 29px;
  font-weight: 700;
  margin-top: 8px;
}

.stat-sub {
  font-size: 11px;
  color: #94a3b8;
  margin-top: 5px;
}

.c360-toolbar {
  display: flex;
  gap: 12px;
  margin-bottom: 18px;
}

.search-box {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  background: white;
  border: 1px solid #dce2ea;
  border-radius: 8px;
  padding: 0 12px;
}

.search-box input {
  width: 100%;
  border: 0;
  outline: none;
  padding: 11px 0;
}

.c360-toolbar select {
  border: 1px solid #dce2ea;
  background: white;
  border-radius: 8px;
  padding: 0 13px;
  min-width: 150px;
}

.c360-card {
  background: white;
  border: 1px solid #e4e8ef;
  border-radius: 12px;
  overflow: hidden;
}

.card-header {
  padding: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #edf0f4;
}

.card-header h2 {
  margin: 0;
  font-size: 17px;
}

.card-header p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 12px;
}

.result-count {
  color: #64748b;
  font-size: 12px;
}

.table-wrap {
  overflow-x: auto;
}

.c360-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 1100px;
}

.c360-table th {
  background: #f8fafc;
  text-align: left;
  padding: 12px 15px;
  font-size: 11px;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: .4px;
}

.c360-table td {
  padding: 14px 15px;
  border-top: 1px solid #edf0f4;
  font-size: 12px;
}

.student-cell {
  display: flex;
  align-items: center;
  gap: 9px;
}

.student-cell strong {
  display: block;
}

.student-cell small,
.c360-table td small {
  display: block;
  color: #94a3b8;
  margin-top: 3px;
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #eef2ff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
}

.status-pill,
.feedback-pill,
.mode-pill {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 700;
}

.status-scheduled {
  background: #eff6ff;
  color: #2563eb;
}

.status-completed {
  background: #ecfdf5;
  color: #047857;
}

.status-cancelled {
  background: #fef2f2;
  color: #b91c1c;
}

.status-rescheduled {
  background: #fff7ed;
  color: #c2410c;
}

.mode-pill {
  background: #f1f5f9;
  color: #475569;
}

.feedback-done {
  background: #ecfdf5;
  color: #047857;
}

.feedback-pending {
  background: #fff7ed;
  color: #c2410c;
}

.view-btn {
  border: 0;
  background: transparent;
  color: #2563eb;
  font-weight: 600;
  cursor: pointer;
}

.empty-state {
  text-align: center;
  padding: 45px !important;
  color: #94a3b8;
}

.c360-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, .35);
  z-index: 1000;
}

.detail-panel {
  position: absolute;
  right: 0;
  top: 0;
  height: 100%;
  width: 430px;
  background: white;
  padding: 26px;
  overflow-y: auto;
  box-shadow: -8px 0 30px rgba(15, 23, 42, .12);
}

.detail-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding-bottom: 20px;
  border-bottom: 1px solid #edf0f4;
}

.detail-header h2 {
  margin: 0;
  font-size: 22px;
}

.close-btn {
  border: 0;
  background: #f1f5f9;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  font-size: 20px;
  cursor: pointer;
}

.detail-section {
  padding-top: 18px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 13px 0;
  border-bottom: 1px solid #f1f5f9;
}

.detail-row span {
  color: #64748b;
  font-size: 12px;
}

.detail-row strong {
  text-align: right;
  font-size: 12px;
}

@media (max-width: 900px) {
  .c360-stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .c360-toolbar {
    flex-direction: column;
  }

  .c360-toolbar select {
    min-height: 40px;
  }
}
.campus360-tpo-layout,
.tpo-layout,
.tpo-container,
.campus360-skill-intel,
.tpo-dashboard-center {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  z-index: 9999 !important;
  overflow: hidden !important;
  background: #f8fafc !important;
}

.campus360-tpo-layout,
.tpo-layout,
.tpo-container,
.campus360-skill-intel,
.tpo-dashboard-center {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  z-index: 9999 !important;
  overflow: hidden !important;
  background: #f8fafc !important;
}

sp_widget.script:
(function() {
  try { data.chatbotWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {}); } catch(e) {}

    data.interviews = [];

    data.stats = {
        total: 0,
        scheduled: 0,
        completed: 0,
        feedbackPending: 0
    };

    var interviewGR = new GlideRecord(
        'x_snc_campus360_mock_interview'
    );

    interviewGR.query();

    while (interviewGR.next()) {

        var student = '';
        var studentId = '';

        if (interviewGR.student_reference) {

            var studentGR =
                interviewGR.student_reference.getRefRecord();

            if (studentGR && studentGR.isValidRecord()) {

                student =
                    studentGR.getDisplayValue() || '';

                studentId =
                    studentGR.getValue('student_id') || '';
            }
        }

        var opportunity =
            interviewGR.getDisplayValue(
                'opportunity_reference'
            ) || '';

        var company = '';

        if (interviewGR.opportunity_reference) {

            var opportunityGR =
                interviewGR.opportunity_reference.getRefRecord();

            if (opportunityGR &&
                opportunityGR.isValidRecord()) {

                company =
                    opportunityGR.getDisplayValue(
                        'company_reference'
                    ) || '';
            }
        }

        var status =
            interviewGR.getDisplayValue('interview_status') ||
            interviewGR.getValue('interview_status') ||
            '';

        var mode =
            interviewGR.getDisplayValue('interview_mode') ||
            interviewGR.getValue('interview_mode') ||
            '';

        var interviewer =
            interviewGR.getDisplayValue('interviewer') ||
            interviewGR.getValue('interviewer') ||
            '';

        var interviewDate =
            interviewGR.getDisplayValue('interview_date') || '';

        var interviewTime =
            interviewGR.getDisplayValue('interview_time') || '';

        var feedbackStatus =
            interviewGR.getDisplayValue('feedback_status') ||
            interviewGR.getValue('feedback_status') ||
            '';

        var initials = '';

        if (student) {

            var words =
                student.trim().split(/\s+/);

            if (words.length === 1) {

                initials =
                    words[0].substring(0, 2);

            } else {

                initials =
                    words[0].charAt(0) +
                    words[1].charAt(0);
            }
        }

        initials = initials.toUpperCase();

        data.interviews.push({

            sys_id: interviewGR.getUniqueValue(),

            student: student,

            studentId: studentId,

            opportunity: opportunity,

            company: company,

            interviewDate: interviewDate,

            interviewTime: interviewTime,

            mode: mode,

            interviewer: interviewer,

            status: status,

            feedbackStatus: feedbackStatus,

            initials: initials
        });

        data.stats.total++;

        if (status === 'Scheduled') {
            data.stats.scheduled++;
        }

        if (status === 'Completed') {
            data.stats.completed++;
        }

        if (!feedbackStatus ||
            feedbackStatus === 'Pending') {

            data.stats.feedbackPending++;
        }
    }

})();

try {
  data.aiWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {});
  data.chatbotWidget = data.aiWidget;
} catch(e) {}
